  const indeg = new Array(num_courses).fill(0);
  for (const [c, p] of prerequisites) { adj[p].push(c); indeg[c]++; }
  const q: number[] = [];
  for (let i = 0; i < num_courses; i++) if (indeg[i] === 0) q.push(i);
